% Each field has subfields 'DR' and 'WC'
% 'DR' and 'WC' are (n x 1) where 'n' = the number of move or non-move trials in that context
MoveNonMove = findMoveNonMoveTrix(meta, obj, trials2cutoff, cond2use, params, me, times);

